def load_rows(rows, conn):
    cursor = conn.cursor()
    try:
        cursor.execute("TRUNCATE TABLE Staging.ProductSnapshot;")
        cursor.executemany(
            "INSERT INTO Staging.ProductSnapshot "
            "(ProductName, Quantity, UnitPrice) VALUES (?, ?, ?);",
            rows
        )
        conn.commit()
        return len(rows)
    except pyodbc.Error:
        conn.rollback()
        raise
